import org.openenglish.reader.*;
import org.json.*;
import java.nio.file.*;
import java.util.*;

/** Cross-language fixtures generated by the pinned upstream implementation, not the Java port. */
public final class JourneyPhonesTest {
 static int count;static void ok(boolean b,String m){if(!b)throw new AssertionError(m);count++;}
 static JSONObject json(String p)throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get(p)),"UTF-8"));}
 static float[][] logits(JSONArray ids,int width){float[][] z=new float[ids.length()][width];for(int i=0;i<z.length;i++){Arrays.fill(z[i],-12);z[i][ids.optInt(i)]=12;}return z;}
 public static void main(String[] args)throws Exception{
  String assets="app/src/main/assets/journey/";JSONObject rules=json(assets+"phone-rules.json"),refs=json(assets+"phone-reference.json"),fixture=json("tests/phone-upstream-fixtures.json");JourneyPhones core=new JourneyPhones(rules);int width=rules.getJSONArray("vocab").length();
  JSONArray cases=fixture.getJSONArray("cases");for(int i=0;i<cases.length();i++){
   JSONObject c=cases.getJSONObject(i);JourneyPhones.Recognition heard=core.decode(logits(c.getJSONArray("ids"),width));
   ok(new JSONArray(heard.phones).toString().equals(c.getJSONArray("phones").toString()),"CTC normalization "+c.getString("name"));
   if(c.has("reference")){
    JSONObject result=core.compare(heard,refs.getJSONObject(c.getString("reference")));JSONArray words=result.getJSONArray("words"),expected=c.getJSONArray("words");
    for(int j=0;j<words.length();j++){JSONObject w=words.getJSONObject(j),e=expected.getJSONObject(j);ok(w.getString("actual").equals(e.getString("actual")),"word alignment "+c.getString("name"));ok(w.getBoolean("flagged")==e.getBoolean("flagged"),"upstream flag "+c.getString("name"));ok(Math.abs(w.getDouble("confidence")-e.getDouble("confidence"))<.0001,"posterior weighting "+c.getString("name"));}
    if(c.getString("reference").equals("think")){String text=JourneyPhones.feedback(result);ok(text.contains("舌尖"),"single-word contrast gives actionable mouth guidance");ok(text.contains("短词不作确定判断"),"no definite short-word diagnosis");}
   }
  }
  try{core.decode(new float[][]{{Float.NaN}});throw new AssertionError("bad output accepted");}catch(IllegalArgumentException expected){count++;}
  String uncertain=JourneyPhones.feedback(new JSONObject().put("usable",false));ok(uncertain.contains("暂不判断"),"uncertain recording is not scored");
  JSONObject correct=core.compare(core.decode(logits(new JSONArray("[0,38,38,0,17,17,0,18,18,0]"),width)),refs.getJSONObject("ship"));ok(!JourneyPhones.feedback(correct).contains("100"),"no fabricated numeric accuracy");
  System.out.println("OpenPronounce compatibility checks: "+count);
 }
}
